import{_ as r,l as n,o as e,c as o,v as t,p as s,x as l,d as E,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"极值理论 EVT","description":"","frontmatter":{"title":"极值理论 EVT","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/evt.md","filePath":"quant/evt.md","lastUpdated":1789023840000}'),d={name:"quant/evt.md"};function u(c,a,m,_,V,T){const i=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="极值理论-evt" tabindex="-1">极值理论 EVT <a class="header-anchor" href="#极值理论-evt" aria-label="Permalink to &quot;极值理论 EVT&quot;">​</a></h1><div class="epigraph"><p>保险与金融里真正贵的是尾巴，不是中心；用正态或历史分位数外推「还没见过的损失」，需要极值理论给出的极限律，而不是把样本最大值当答案。</p><footer>—— Embrechts, Klüppelberg and Mikosch, Modelling Extremal Events for Insurance and Finance, Springer 1997</footer></div><p><a href="/quant/iv-vs-rv">上一课</a>把无模型隐含方差与已实现积分方差对齐，差额含预测误差与方差风险溢价；VIX 不是对未来波动的无偏点预测。缺口转到尾部：平均亏损与隐含–已实现差都不管「超过高阈值之后还长什么样」。Fisher–Tippett–Gnedenko 给块极大值广义极值极限；Pickands–Balkema–de Haan 给超阈值超出量广义帕累托极限。本课写 EVT 作为尾部的渐近模型：估什么、阈值怎么选、以及为何相关为零仍可能同爆。不重推方差互换复制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>隐含与已实现对齐之后，差额是预测误差加方差风险溢价；两边都不管超过高阈值之后损失还长什么样。设日损失 \\(X\\) 有分布 \\(F\\)。VaR 是 \\(F\\) 的高分位数，Expected Shortfall 是超过 VaR 的条件期望。样本里超过 99.5% 的点很少，经验分位数方差极大；用全样本拟合的正态或 \\(t\\) 又把中心的拟合误差带进尾巴。问题是找一种只使用尾巴形状的极限，而不是把整个 \\(F\\) 估对。</p><p>两个操作定义。<strong>块极大值</strong>：把样本切成 \\(m\\) 块，每块取最大，\\(M_n\\) 经中心化、尺度化后，若有非退化极限，则必为广义极值（GEV）——Gumbel、Fréchet 或 Weibull 三型。<strong>超阈值（POT）</strong>：给定高阈值 \\(u\\)，超出量 \\(X-u\\mid X\\gt u\\) 在 \\(u\\to\\) 端点时逼近广义帕累托（GPD），形状参数 \\(\\xi\\) 与 GEV 是同一个尾指数。金融日损失通常属 Fréchet 域：\\(\\xi\\gt 0\\)，尾像幂律，矩是否存在取决于 \\(\\xi\\)。</p><h3 id="正则变化与「均值可能不存在」" tabindex="-1">正则变化与「均值可能不存在」 <a class="header-anchor" href="#正则变化与「均值可能不存在」" aria-label="Permalink to &quot;正则变化与「均值可能不存在」&quot;">​</a></h3><p>若 \\(\\bar F(x)=1-F(x)\\) 正则变化指数 \\(-\\alpha\\)，则 \\(\\xi=1/\\alpha\\)。\\(\\alpha\\le 2\\) 时方差无穷，\\(\\alpha\\le 1\\) 时均值无穷。保险里的大赔付、某些资产的日损失，经验 Hill 图会把 \\(\\alpha\\) 画到 2 附近，是否小于 2 对组合分散化是否成立是一等结论：方差有限才能谈 Markowitz；方差无限时，线性相关与方差贡献都没有定义。EVT 要先回答「几阶矩存在」，再谈 VaR 数字。</p><p><span class="marginnote">把「极端」理解成「样本里最大的那几天」是循环的。EVT 的极端是渐近：阈值升高时超出量的形状稳定到 GPD。阈值太低，中心污染；太高，点太少。诊断靠平均超出函数是否近似线性，而不是靠业务上「我觉得 3σ 以外都算极端」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>GEV 拟合块极大。</strong> 年极大或月极大样本小，适合再保险的「一年最大赔付」，对交易账簿的日 VaR 浪费数据。形状、位置、尺度可用极大似然或概率加权矩；分位数由 GEV 反函数给出。块长是带宽：太短则块内极值不像极大值，太长则样本更少。</p><p><strong>GPD 拟合 POT。</strong> 这是市场风险更常用的一条。选 \\(u\\)，对 \\(\\{X_i-u:X_i\\gt u\\}\\) 拟合</p> \\[G_{\\xi,\\beta}(x)=1-\\left(1+\\xi x/\\beta\\right)^{-1/\\xi},\\qquad x\\ge 0,\\ \\ 1+\\xi x/\\beta\\gt 0. \\]<p>\\(\\xi=0\\) 时退回指数。超过 \\(u\\) 的 VaR、ES 有闭式。阈值选择用平均超出图、Hill 图、参数对 \\(u\\) 的稳定性。McNeil 与 Frey 建议先用 GARCH 去条件异方差，再对标准化残差做 EVT，避免把波动聚类当成厚尾。</p><p>Hill 估计对正尾、\\(\\xi\\gt 0\\) 常用：\\(\\hat\\xi=k^{-1}\\sum_{j=1}^k \\ln X_{(j)}-\\ln X_{(k+1)}\\)，其中 \\(X_{(j)}\\) 为降序统计量。\\(k\\) 同样是带宽。Hill 图应在某段 \\(k\\) 上大致平台；没有平台就不要报一个 \\(\\alpha\\)。</p><h3 id="从单尾到多元极值" tabindex="-1">从单尾到多元极值 <a class="header-anchor" href="#从单尾到多元极值" aria-label="Permalink to &quot;从单尾到多元极值&quot;">​</a></h3><p>组合损失不是单资产损失之和那么简单：尾部依赖决定是否「一起爆」。多元 EVT 用极值 Copula、Pickands 依赖函数、或经验上的尾依赖系数</p> \\[\\lambda=\\lim_{u\\to 1}\\Pr(F_2(X_2)\\gt u\\mid F_1(X_1)\\gt u). \\]<p>高斯 Copula 的 \\(\\lambda=0\\)（除非完全相关）；\\(t\\) Copula 与 Clayton 可以有正的下尾依赖。Embrechts、McNeil 与 Straumann 强调：线性相关低，不等于极端同向概率低。EVT 与 <a href="/quant/copula">Copula</a> 在这里交接：边缘用 GPD，依赖用能产生尾依赖的 Copula。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>块极大值的极限来自独立同分布的极值吸引域：只有三种非退化极限，形状参数决定尾巴是指数级还是幂律。POT 的机制是：高阈值之上，超出量的条件分布被「记忆消去」到只剩 \\(\\xi\\) 与一个尺度。这解释了为何可以用短样本谈「未见过的分位数」——你外推的是极限族，不是经验分布的最后一个点。</p><p>次指数族给出另一句机制性的话：大损失往往由<strong>单笔</strong>主导，而不是许多中等损失相加。这对操作风险、信用组合的大额违约、以及厚尾资产的「分散化幻觉」都成立：把独立次指数变量相加，和的尾由最大项的尾决定。正态世界里平方根 \\(n\\) 的分散化，在 \\(\\xi\\) 较大时会失效。</p><p><span class="marginnote">波动聚类会让「独立同分布」的块极大值假设作假。连续多日大损失是条件方差升高，不一定是无条件尾巴变厚。先过滤 GARCH 或已实现波动，再对残差做 EVT，是为了把两种现象拆开；把生收益直接套 GPD，会把聚类算进 \\(\\xi\\)。</span></p><h3 id="诊断先于数字" tabindex="-1">诊断先于数字 <a class="header-anchor" href="#诊断先于数字" aria-label="Permalink to &quot;诊断先于数字&quot;">​</a></h3><p>平均超出函数 \\(e(u)=\\mathbb{E}[X-u\\mid X\\gt u]\\)：GPD 下它对 \\(u\\) 线性，斜率 \\(\\xi/(1-\\xi)\\)。图上弯、折，说明单一 GPD 不够，或阈值区内有体制切换。Hill 图若单调下降而无平台，\\(\\alpha\\) 不可识别。这些图比报一个 99.9% VaR 更重要。回测高分位数需要很长的样本，Kupiec 在极端水平上几乎没有功效——EVT 的外推不能用常规 VaR 回测「证实」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>EVT 是渐近论，不是保证小样本分位数无偏。十年日数据，99.9% 仍是外推。结构突变（交易所规则、涨跌停、货币危机）会让吸引域在样本中途改变。有限上界（Weibull 域）在有涨跌停的市场可能更贴切，却常被默认成 Fréchet。</p><p>阈值与 \\(k\\) 是主观带宽，应报告敏感区间而不是一个点估计。序列依赖未过滤时，有效样本小于 \\(n\\)，标准误会假窄。多元时，成分不同步、缺失与<a href="/quant/microstructure-noise">微观结构</a>会污染极高分位的「联合超阈」。</p><p>不要用 EVT 去拟合收益的中心；不要把 GEV 的位置参数解释成「平均极端损失」。不要在组合层面套一元 GPD 却用高斯相关去加总——尾依赖才是加总误差的主项。监管乘数与内部模型若宣称「EVT 已覆盖未知未知」，只是把外推风险换了个名字。</p><p><span class="marginnote">Embrechts 等人反复写的不是「请用 GPD」，而是「厚尾下均值、相关、分散化这些中心极限直觉会坏」。先检查矩是否存在、尾依赖是否为零，再决定 VaR 加总与风险预算有没有定义。</span></p>',30)),(e(),s(h,null,{default:l(()=>[p(i,{id:"mermaid-84",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%8D%9F%E5%A4%B1%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20FLT%5B%22%E5%8F%AF%E9%80%89%3A%20GARCH%20%E8%BF%87%E6%BB%A4%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20FLT%20--%3E%20BM%5B%22%E5%9D%97%E6%9E%81%E5%A4%A7%E5%80%BC%22%5D%0A%20%20FLT%20--%3E%20POT%5B%22%E8%B6%85%E9%98%88%E5%80%BC%E8%B6%85%E5%87%BA%E9%87%8F%22%5D%0A%20%20BM%20--%3E%20GEV%5B%22GEV%3A%20Gumbel%20%2F%20Fr%C3%A9chet%20%2F%20Weibull%22%5D%0A%20%20POT%20--%3E%20GPD%5B%22GPD%20%E5%BD%A2%E7%8A%B6%20%CE%BE%22%5D%0A%20%20GPD%20--%3E%20Q%5B%22%E9%AB%98%E5%88%86%E4%BD%8D%20VaR%20%2F%20ES%22%5D%0A%20%20GEV%20--%3E%20Q%0A%20%20X%20--%3E%20DEP%5B%22%E5%A4%9A%E5%85%83%3A%20%E5%B0%BE%E4%BE%9D%E8%B5%96%20%CE%BB%22%5D%0A%20%20DEP%20--%3E%20Q%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>块极大值极限是 GEV，超阈值超出量极限是 GPD，形状参数同一，决定尾是幂律还是更薄。</li><li>金融损失常落在 Fréchet 域；\\(\\xi\\) 足够大时方差甚至均值不存在，相关与方差分散化没有定义。</li><li>POT 加平均超出图、Hill 图是实务主路径；波动聚类应先过滤再估尾。</li><li>线性不相关可以有尾依赖；组合极端要用多元 EVT 或带尾依赖的 Copula。</li><li>阈值是带宽，高分位是外推，常规回测几乎验不出对错。</li><li>出处：Embrechts, Klüppelberg, Mikosch, <em>Modelling Extremal Events</em>, 1997；吸引域与 GPD 见 Pickands、Balkema–de Haan；风险管线见 McNeil, Frey, Embrechts, <em>Quantitative Risk Management</em>；GARCH 残差上的 EVT 见 McNeil and Frey, 2000。</li></ul>',2))])}const b=r(d,[["render",u]]);export{P as __pageData,b as default};
